CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS courses (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, lang TEXT NOT NULL DEFAULT 'nl', price_eur INTEGER NOT NULL DEFAULT 0, is_published INTEGER NOT NULL DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stages (id TEXT PRIMARY KEY, course_id TEXT NOT NULL, title TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS lessons (id TEXT PRIMARY KEY, stage_id TEXT NOT NULL, title TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('video','text','quiz','exam')), content TEXT, video_url TEXT, duration_min INTEGER DEFAULT 0, position INTEGER NOT NULL DEFAULT 0, is_free_preview INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (stage_id) REFERENCES stages(id));
CREATE TABLE IF NOT EXISTS quiz_questions (id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL, question TEXT NOT NULL, option_a TEXT NOT NULL, option_b TEXT NOT NULL, option_c TEXT NOT NULL, option_d TEXT NOT NULL, correct_index INTEGER NOT NULL, position INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (lesson_id) REFERENCES lessons(id));
CREATE TABLE IF NOT EXISTS enrollments (id INTEGER PRIMARY KEY AUTOINCREMENT, user_email TEXT NOT NULL, course_id TEXT NOT NULL, stripe_session_id TEXT, activation_date DATE, expiry_date DATE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_email, course_id));
CREATE TABLE IF NOT EXISTS quiz_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, user_email TEXT NOT NULL, lesson_id TEXT NOT NULL, answers TEXT NOT NULL, score INTEGER NOT NULL, passed INTEGER NOT NULL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lesson_progress (id INTEGER PRIMARY KEY AUTOINCREMENT, user_email TEXT NOT NULL, lesson_id TEXT NOT NULL, completed_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_email, lesson_id));
